// ---------------------------------------------------------------------------
// Pipeline stages — mirrors the researched architecture so the mockup shows
// what the user is actually waiting on, not a generic spinner.
// ---------------------------------------------------------------------------

export function formatTime(sec: number): string {
  const m = Math.floor(sec / 60);
  const s = Math.floor(sec % 60);
  return `${m}:${s.toString().padStart(2, "0")}`;
}
